"""matplotlib.rcsetup — rcParams validation."""


def validate_bool(b):
    if isinstance(b, str):
        return b.lower() in ('true', '1', 'yes', 'on')
    return bool(b)

def validate_float(s):
    return float(s)

def validate_int(s):
    return int(s)

def validate_string(s):
    return str(s)

def validate_color(s):
    """Accept any matplotlib color spec (named, hex, RGB(A) tuple,
    'C0'..'C9', single-letter code). Returns the input unchanged when
    valid, raises :class:`ValueError` otherwise."""
    if s is None or s == 'none':
        return 'none'
    try:
        from matplotlib.colors import to_rgba
        to_rgba(s)
        return s
    except (ValueError, TypeError) as e:
        raise ValueError(f'{s!r} is not a valid color spec: {e}')


_FONTSIZES = {'xx-small', 'x-small', 'small', 'medium', 'large', 'x-large',
               'xx-large', 'larger', 'smaller'}


def validate_fontsize(s):
    """Accept a numeric size in points OR one of the named sizes."""
    if isinstance(s, str):
        if s in _FONTSIZES:
            return s
        try:
            return float(s)
        except ValueError as e:
            raise ValueError(f'{s!r} is not a valid font size '
                             f'(use one of {sorted(_FONTSIZES)} or a number): {e}')
    return float(s)


_FONTSTYLES = {'normal', 'italic', 'oblique'}


def validate_fontstyle(s):
    if s not in _FONTSTYLES:
        raise ValueError(f'{s!r} is not a valid fontstyle; '
                         f'pick one of {sorted(_FONTSTYLES)}')
    return s


_FONTWEIGHTS = {
    'ultralight', 'light', 'normal', 'regular', 'book', 'medium',
    'roman', 'semibold', 'demibold', 'demi', 'bold', 'heavy',
    'extra bold', 'black',
}


def validate_fontweight(s):
    """Numeric (100-900) or a named weight."""
    if isinstance(s, (int, float)):
        v = int(s)
        if not 0 < v <= 1000:
            raise ValueError(f'weight {v} out of [1, 1000]')
        return v
    if s in _FONTWEIGHTS:
        return s
    try:
        return int(s)
    except (TypeError, ValueError) as e:
        raise ValueError(f'{s!r} is not a valid fontweight (one of '
                          f'{sorted(_FONTWEIGHTS)} or numeric): {e}')

def validate_dpi(s):
    if s == 'figure':
        return s
    return float(s)

def cycler(*args, **kwargs):
    """Simple cycler stub."""
    if args and hasattr(args[0], '__iter__'):
        return list(args[0])
    return [{k: v[i % len(v)] for k, v in kwargs.items()}
            for i in range(max(len(v) for v in kwargs.values()))]


# Default rcParams dict
defaultParams = {}


# ─── Added: missing public validators from upstream rcsetup.py ─────
#
# These accept a value, coerce/validate it, and raise ``ValueError`` on
# bad input — the contract upstream uses for the rcParams type system.
# Most of them sit on top of :func:`validate_string` / :func:`validate_float`
# with a domain check tacked on.

import re as _re


def _make_keyed_validator(name, allowed):
    def _check(s):
        if s not in allowed:
            raise ValueError(f"{s!r} is not a valid value for {name}; "
                             f"supported values are {sorted(allowed)}")
        return s
    _check.__name__ = f'validate_{name}'
    return _check


validate_backend = _make_keyed_validator('backend', {
    'agg', 'tkagg', 'macosx', 'qtagg', 'qt5agg', 'qt4agg', 'gtk3agg',
    'gtk4agg', 'wxagg', 'webagg', 'nbagg', 'svg', 'pdf', 'ps', 'pgf',
    'plotly', 'module://',  # 'module://...' prefix style
})


def validate_aspect(s):
    """Aspect-ratio: ``'auto'``, ``'equal'``, or a positive float."""
    if isinstance(s, str):
        if s in ('auto', 'equal'):
            return s
        return float(s)
    return float(s)


def validate_floatlist(s):
    """Comma-separated list of floats. Tolerates trailing commas and
    whitespace, returns a plain ``list[float]``."""
    if isinstance(s, str):
        if not s.strip():
            return []
        return [float(x) for x in s.split(',') if x.strip()]
    return [float(x) for x in s]


def validate_intlist(s):
    """As :func:`validate_floatlist` but for integers."""
    if isinstance(s, str):
        if not s.strip():
            return []
        return [int(x) for x in s.split(',') if x.strip()]
    return [int(x) for x in s]


def validate_stringlist(s):
    """Comma-separated list of strings — preserves order, drops empties."""
    if isinstance(s, str):
        return [x.strip() for x in s.split(',') if x.strip()]
    return [str(x) for x in s]


def validate_colorlist(s):
    """List of colour specs — same parsing as :func:`validate_stringlist`,
    but each element is round-tripped through :func:`validate_color`
    so callers get a uniform error on bad colours."""
    return [validate_color(x) for x in validate_stringlist(s)]


def validate_color_or_auto(s):
    if s == 'auto':
        return s
    return validate_color(s)


def validate_color_or_inherit(s):
    if s == 'inherit':
        return s
    return validate_color(s)


def validate_color_for_prop_cycle(s):
    return validate_color(s)


def validate_anylist(s):
    """List of arbitrary tokens — no per-element validation. Splits a
    string on commas; passes lists through."""
    if isinstance(s, str):
        return [x.strip() for x in s.split(',') if x.strip()]
    return list(s)


def validate_path_exists(s):
    """File path that must exist on disk. Returns the path string.
    Used for things like the LaTeX-preamble file location."""
    import os
    if s is None or s == '':
        return s
    if not os.path.exists(s):
        raise ValueError(f"{s!r} does not exist")
    return s


def validate_animation_writer_path(s):
    """Path to an animation-writer executable (ffmpeg, imagemagick, ...).
    Accepts a bare executable name (looked up via ``PATH``) or a full
    path; doesn't require the binary to actually exist (matches
    upstream's lenient behaviour at config-load time).
    """
    return str(s) if s is not None else ''


validate_axes_titlelocation = _make_keyed_validator(
    'axes.titlelocation', {'left', 'center', 'right'})

validate_axes_xlocation = _make_keyed_validator(
    'axes.xlocation', {'top', 'bottom'})

validate_axes_ylocation = _make_keyed_validator(
    'axes.ylocation', {'left', 'right'})


def validate_axisbelow(s):
    """``True``, ``False``, or ``'line'`` (axisbelow draws gridlines
    below regular lines but above patches)."""
    if isinstance(s, str):
        low = s.lower()
        if low == 'line':
            return 'line'
        if low in ('true', '1', 'yes', 'on'):
            return True
        if low in ('false', '0', 'no', 'off'):
            return False
    return bool(s)


def validate_bbox(s):
    """Bbox spec: ``'tight'``, ``'standard'``, or ``None``."""
    if s is None or s == 'standard' or s == 'tight':
        return s
    raise ValueError(f"bbox must be 'tight', 'standard', or None; got {s!r}")


def validate_dashlist(s):
    """Dash sequence — a flat list of ``(on, off)`` lengths, or a list
    of such lists for multiple dash styles."""
    if isinstance(s, str):
        # "5,2,5,2" → [5.0, 2.0, 5.0, 2.0]
        return validate_floatlist(s)
    return [float(x) for x in s]


def validate_hatch(s):
    """Hatch pattern string. Allowed characters are documented by
    :data:`_hatch_types`. Any other characters trigger a ValueError."""
    allowed = set("/\\|-+xXoO.*")
    if any(c not in allowed for c in (s or '')):
        raise ValueError(f"hatch pattern {s!r} contains illegal characters")
    return s or ''


def validate_hatchlist(s):
    if isinstance(s, str):
        return [validate_hatch(x) for x in s.split(',')]
    return [validate_hatch(x) for x in s]


def validate_markevery(s):
    """``markevery`` accepts: ``None``, an int, a slice, a tuple of
    floats, or a list. We pass these through largely unchanged but
    reject obvious garbage."""
    if s is None:
        return None
    if isinstance(s, (int, slice, list, tuple)):
        return s
    if isinstance(s, float) and 0 <= s <= 1:
        return s
    raise ValueError(f"invalid markevery spec: {s!r}")


def validate_sketch(s):
    """``axes.sketch_params``: a tuple ``(scale, length, randomness)``
    or ``None``."""
    if s is None or s == 'None':
        return None
    if isinstance(s, str):
        return tuple(validate_floatlist(s))
    return tuple(float(x) for x in s)


def validate_whiskers(s):
    """Boxplot whiskers: a float, or a 2-list ``[lo, hi]``."""
    if isinstance(s, (list, tuple)):
        return [float(x) for x in s]
    return float(s)


def validate_ps_distiller(s):
    """PostScript distiller: ``'ghostscript'``, ``'xpdf'``, or ``None``."""
    if s in (None, 'None', ''):
        return None
    if s in ('ghostscript', 'xpdf'):
        return s
    raise ValueError(f"unknown ps.distiller: {s!r}")


validate_pgf_texsystem = _make_keyed_validator(
    'pgf.texsystem', {'xelatex', 'lualatex', 'pdflatex'})


# Re-export everything new for ``from matplotlib.rcsetup import *``.
__all__ = sorted({k for k in globals() if k.startswith('validate_')}
                 | {'cycler', 'defaultParams', '_re'})


# ─── Added: more validators from upstream rcsetup.py ───────────────


class ValidateInStrings:
    """Callable validator that checks the input against a fixed set of
    allowed strings. Used to build many of the keyed validators that
    upstream defines inline in rcsetup."""

    def __init__(self, key, valid, ignorecase=False):
        self.key = key
        self.ignorecase = ignorecase
        self.valid = {v.lower() if ignorecase else v: v for v in valid}

    def __call__(self, s):
        lookup = s.lower() if (self.ignorecase and isinstance(s, str)) else s
        if lookup in self.valid:
            return self.valid[lookup]
        raise ValueError(
            f"{s!r} is not a valid value for {self.key}; "
            f"supported values are {sorted(self.valid.values())}")


def validate_any(s):
    """Accept anything — used as the default for rcParams that don't
    have a stricter type."""
    return s


def validate_cycler(s):
    """Validate a property cycler. Accepts a cycler instance, a list of
    dicts, or a string spec (``'cycler("color", ...)'``). The shim
    doesn't construct a real Cycler, just passes the value through."""
    if isinstance(s, str):
        # Crude: evaluate the cycler() call expression.
        try:
            return eval(s, {'cycler': cycler})
        except Exception:
            return s
    return s


def validate_fillstyle(s):
    """Marker fill style — one of ``'full'``, ``'left'``, ``'right'``,
    ``'bottom'``, ``'top'``, ``'none'``."""
    if s in ('full', 'left', 'right', 'bottom', 'top', 'none'):
        return s
    raise ValueError(f"invalid fillstyle: {s!r}")


def validate_fillstylelist(s):
    """List of fillstyles — comma-separated."""
    if isinstance(s, str):
        return [validate_fillstyle(x.strip()) for x in s.split(',') if x.strip()]
    return [validate_fillstyle(x) for x in s]


def validate_float_or_None(s):
    """``None`` or a float."""
    if s is None or s == 'None' or s == '':
        return None
    return float(s)


def validate_int_or_None(s):
    """``None`` or an int."""
    if s is None or s == 'None' or s == '':
        return None
    return int(s)


def validate_font_properties(s):
    """Font-properties dict spec. The shim accepts any string and lets
    FontProperties resolve it lazily."""
    if isinstance(s, dict):
        return s
    return str(s)


def validate_fontsize_None(s):
    if s is None or s == 'None':
        return None
    return validate_fontsize(s)


def validate_fontsizelist(s):
    if isinstance(s, str):
        return [validate_fontsize(x.strip()) for x in s.split(',') if x.strip()]
    return [validate_fontsize(x) for x in s]


def validate_grid_axis(s):
    if s in ('both', 'x', 'y'):
        return s
    raise ValueError(f"grid_axis must be 'both', 'x', or 'y'; got {s!r}")


def validate_grid(s):
    """Grid spec — boolean or one of {major, minor, both}."""
    if isinstance(s, bool):
        return s
    if s in ('major', 'minor', 'both', 'auto'):
        return s
    return validate_bool(s)


def validate_movie_writer(s):
    """Writer-name spec for animation.writer rcParam."""
    return str(s)


def validate_papersize(s):
    """One of the standard paper sizes or ``'auto'`` / ``'letter'``."""
    return str(s)


def validate_path(s):
    """Generic path — leave as string."""
    return str(s)


def validate_qt4(s):
    if s in (None, 'PyQt4', 'PySide'):
        return s
    raise ValueError(f"invalid qt4 backend: {s!r}")


def validate_qt5(s):
    if s in (None, 'PyQt5', 'PySide2'):
        return s
    raise ValueError(f"invalid qt5 backend: {s!r}")


# ─── Added: remaining validators from upstream rcsetup.py ───────────


def validate_fontstretch(s):
    """Font-stretch keyword or numeric weight (1-1000)."""
    if isinstance(s, (int, float)):
        return float(s)
    valid = {'ultra-condensed', 'extra-condensed', 'condensed',
             'semi-condensed', 'normal', 'semi-expanded', 'expanded',
             'extra-expanded', 'ultra-expanded'}
    if s in valid:
        return s
    try:
        return float(s)
    except (TypeError, ValueError):
        raise ValueError(f"invalid font-stretch: {s!r}")


def validate_fonttype(s):
    """PostScript font type — 3 (Type 3) or 42 (TrueType)."""
    try:
        s = int(s)
    except (TypeError, ValueError):
        raise ValueError(f"font type must be 3 or 42, got {s!r}")
    if s not in (3, 42):
        raise ValueError(f"font type must be 3 or 42, got {s!r}")
    return s


def validate_hist_bins(s):
    """``hist.bins`` spec — ``'auto'``, ``'sturges'``, an int, or a list
    of bin edges."""
    if isinstance(s, str):
        if s in ('auto', 'sturges', 'fd', 'doane', 'scott', 'rice',
                 'sqrt', 'stone'):
            return s
        # Comma-separated list of edges.
        return [float(x) for x in s.split(',') if x.strip()]
    if hasattr(s, '__iter__'):
        return list(s)
    return int(s)


def validate_markeverylist(s):
    """List of markevery specs — accepts a single spec or a list."""
    if isinstance(s, (list, tuple)):
        return [validate_markevery(x) for x in s]
    return [validate_markevery(s)]


def validate_string_or_None(s):
    if s is None or s == 'None':
        return None
    return str(s)
